MAP
    NAME "SS_MAP_AGUA_CRUCEROS"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
            'wfs_title' 'Cruceros'
            'wfs_enable_request' '*'
            'wfs_getfeature_formatlist' 'gml,geojson'
            'gml_featureid' 'gid'
            'gml_include_items' 'all'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_cruceros.log"
    DEBUG 0
    LAYER
        PROJECTION
            'init=epsg:32614'
        END #PROJECTION
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_AGUA_CRUCEROS"
        METADATA
            'ows_title' 'Instalaciones de Sapal'
            'ows_include_items' 'all'
            'gml_include_items' 'all'
        END #METADATA
        INCLUDE 'includes/conexion.map'
        DATA "geometry from cruceros using unique gid using srid=32614"
        STATUS DEFAULT
        TYPE LINE
        CLASS
            NAME "cruceros"
            STYLE
                SYMBOL 'plainline'
                SIZE 5
                COLOR -1 -1 -1
                OUTLINECOLOR 255 0 0
            END #STYLE
        END #CLASS
    END #LAYER
END #MAP